def pylon_get_me(workspace_id=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, workspace_id_used=None, principal_user_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "ply_req_" + uuid.uuid4().hex[:16].upper(),
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "principal_user_id": principal_user_id,
            "status": status,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    try:
        if workspace_id is not None:
            if not isinstance(workspace_id, str):
                e = _err("VALIDATION_ERROR", "workspace_id must be a string")
                _log("pylon_get_me", "error", workspace_id_used=None, principal_user_id=None, error=e["error"])
                return e
            if not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
                e = _err("VALIDATION_ERROR", "workspace_id is present but not a valid workspace ULID", field="workspace_id")
                _log("pylon_get_me", "error", workspace_id_used=None, principal_user_id=None, error=e["error"])
                return e

        workspaces = _load("workspaces.json")
        users_teams = _load("users_teams.json")

        if not isinstance(workspaces, list): workspaces = []
        if not isinstance(users_teams, list): users_teams = []

        # Ambient auth: find any active workspace with an active user.
        # If workspace_id provided, must find an active/in-scope user in that workspace.
        target_wsp = None
        if workspace_id is not None:
            for w in workspaces:
                if isinstance(w, dict) and w.get("id") == workspace_id:
                    target_wsp = w
                    break
            if not target_wsp or target_wsp.get("status") == "deleted":
                e = _err("NOT_FOUND", "Workspace not found")
                _log("pylon_get_me", "error", workspace_id_used=workspace_id, principal_user_id=None, error=e["error"])
                return e
        else:
            # choose any non-deleted workspace to scope context
            for w in workspaces:
                if isinstance(w, dict) and w.get("status") in ("active", "suspended"):
                    target_wsp = w
                    break
            if not target_wsp:
                e = _err("UNAUTHORIZED", "No valid authentication context could be resolved")
                _log("pylon_get_me", "error", workspace_id_used=None, principal_user_id=None, error=e["error"])
                return e

        # Find a principal user row in that workspace
        principal = None
        for u in users_teams:
            if not isinstance(u, dict):
                continue
            if u.get("team_type") != "user":
                continue
            if u.get("workspace_id") != target_wsp.get("id"):
                continue
            if u.get("user_status") == "active":
                principal = u
                break
        if not principal:
            # allow invited as fallback for "me"
            for u in users_teams:
                if not isinstance(u, dict):
                    continue
                if u.get("team_type") != "user":
                    continue
                if u.get("workspace_id") != target_wsp.get("id"):
                    continue
                if u.get("user_status") == "invited":
                    principal = u
                    break

        if not principal:
            e = _err("UNAUTHORIZED", "No authenticated principal available for this workspace")
            _log("pylon_get_me", "error", workspace_id_used=target_wsp.get("id"), principal_user_id=None, error=e["error"])
            return e

        resp = {
            "workspace": {
                "id": target_wsp.get("id"),
                "slug": target_wsp.get("slug"),
                "name": target_wsp.get("name"),
                "status": target_wsp.get("status"),
                "plan": target_wsp.get("plan"),
                "default_timezone": target_wsp.get("default_timezone"),
                "created_at": target_wsp.get("created_at"),
                "updated_at": target_wsp.get("updated_at")
            },
            "principal": {
                "type": "user",
                "user_id": principal.get("user_id"),
                "email": principal.get("email"),
                "full_name": principal.get("full_name"),
                "user_role": principal.get("user_role"),
                "availability_status": principal.get("availability_status"),
                "user_status": principal.get("user_status"),
                "team_id": principal.get("team_id")
            },
            "permissions": {
                "can_read": True,
                "can_write": principal.get("user_role") in ("owner", "admin", "agent"),
                "role": principal.get("user_role")
            }
        }
        _log("pylon_get_me", "ok", workspace_id_used=target_wsp.get("id"), principal_user_id=principal.get("user_id"), error=None)
        return resp
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("pylon_get_me", "error", workspace_id_used=workspace_id, principal_user_id=None, error=e["error"])
        return e

def pylon_get_contacts(workspace_id, query=None, account_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, principal_user_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "ply_req_" + uuid.uuid4().hex[:16].upper(),
            "endpoint": "pylon_get_contacts",
            "workspace_id": workspace_id,
            "principal_user_id": principal_user_id,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
            e = _err("VALIDATION_ERROR", "workspace_id must be a valid workspace ULID", field="workspace_id")
            _log("error", None, e["error"])
            return e

        if query is not None and not isinstance(query, str):
            e = _err("VALIDATION_ERROR", "query must be a string", field="query")
            _log("error", None, e["error"])
            return e

        if account_id is not None:
            if not isinstance(account_id, str) or not re.match(r"^(ply_acc|ply_con)_[0-9A-Z]{10,}$", account_id):
                e = _err("VALIDATION_ERROR", "account_id must be a valid customer id", field="account_id")
                _log("error", None, e["error"])
                return e

        if status is not None and status not in ("active", "archived", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status", field="status")
            _log("error", None, e["error"])
            return e

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
            _log("error", None, e["error"])
            return e

        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at"):
            e = _err("VALIDATION_ERROR", "Invalid sort field", field="sort")
            _log("error", None, e["error"])
            return e

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "Invalid order", field="order")
            _log("error", None, e["error"])
            return e

        # Authenticate ambiently: must have at least one user row in workspace
        users_teams = _load("users_teams.json")
        principal_user_id = None
        if isinstance(users_teams, list):
            for u in users_teams:
                if isinstance(u, dict) and u.get("team_type") == "user" and u.get("workspace_id") == workspace_id and u.get("user_status") in ("active", "invited"):
                    principal_user_id = u.get("user_id")
                    break
        if principal_user_id is None:
            e = _err("UNAUTHORIZED", "No valid authentication context for this workspace")
            _log("error", None, e["error"])
            return e

        workspaces = _load("workspaces.json")
        wsp = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("id") == workspace_id:
                    wsp = w
                    break
        if not wsp or wsp.get("status") == "deleted":
            e = _err("NOT_FOUND", "Workspace not found")
            _log("error", principal_user_id, e["error"])
            return e

        customers = _load("customers.json")
        if not isinstance(customers, list):
            customers = []

        # Validate account_id exists & is account in same workspace if provided
        account_row = None
        if account_id is not None:
            for c in customers:
                if isinstance(c, dict) and c.get("id") == account_id and c.get("workspace_id") == workspace_id:
                    account_row = c
                    break
            if not account_row:
                e = _err("NOT_FOUND", "Account not found", field="account_id")
                _log("error", principal_user_id, e["error"])
                return e
            if account_row.get("entity_type") != "account":
                e = _err("VALIDATION_ERROR", "account_id must reference an account customer record", field="account_id")
                _log("error", principal_user_id, e["error"])
                return e

        # Build lookup for accounts
        accounts_by_id = {c.get("id"): c for c in customers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("entity_type") == "account"}

        def _norm(s):
            return (s or "").strip().lower()

        qn = _norm(query) if query else None

        contacts = []
        for c in customers:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            if c.get("entity_type") != "contact":
                continue
            if c.get("status") == "deleted" and status is None:
                # by default exclude deleted for list-like reads
                continue
            if status is not None and c.get("status") != status:
                continue
            if account_id is not None and c.get("account_id") != account_id:
                continue
            if qn:
                acct = accounts_by_id.get(c.get("account_id"))
                hay = " ".join([
                    _norm(c.get("contact_name")),
                    _norm(c.get("contact_email")),
                    _norm(acct.get("company_name") if isinstance(acct, dict) else None)
                ])
                if qn not in hay:
                    continue
            contacts.append(c)

        # Sort
        def _dt_key(v):
            if not isinstance(v, str):
                return ""
            return v
        reverse = (order == "desc")
        contacts.sort(key=lambda r: _dt_key(r.get(sort)), reverse=reverse)

        # Cursor pagination: cursor is base64("offset:<n>")
        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
                _log("error", principal_user_id, e["error"])
                return e
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                raw_s = raw.decode("utf-8")
                if not raw_s.startswith("offset:"):
                    raise ValueError("bad cursor")
                offset = int(raw_s.split(":", 1)[1])
                if offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                e = _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
                _log("error", principal_user_id, e["error"])
                return e

        total = len(contacts)
        page = contacts[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

        resp = {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort": sort,
                "order": order
            }
        }
        _log("ok", principal_user_id, None)
        return resp
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", None, e["error"])
        return e

def pylon_get_issues(workspace_id, query=None, status=None, priority=None, assignee_user_id=None, team_id=None, account_id=None, contact_id=None, tag_ids=None, ticket_form_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, principal_user_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "ply_req_" + uuid.uuid4().hex[:16].upper(),
            "endpoint": "pylon_get_issues",
            "workspace_id": workspace_id,
            "principal_user_id": principal_user_id,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
            e = _err("VALIDATION_ERROR", "workspace_id must be a valid workspace ULID", field="workspace_id")
            _log("error", None, e["error"])
            return e

        if query is not None and not isinstance(query, str):
            e = _err("VALIDATION_ERROR", "query must be a string", field="query")
            _log("error", None, e["error"])
            return e

        if status is not None and status not in ("open", "in_progress", "pending", "snoozed", "resolved", "closed", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status", field="status")
            _log("error", None, e["error"])
            return e

        if priority is not None and priority not in ("low", "medium", "high", "urgent"):
            e = _err("VALIDATION_ERROR", "Invalid priority", field="priority")
            _log("error", None, e["error"])
            return e

        if assignee_user_id is not None:
            if not isinstance(assignee_user_id, str) or not re.match(r"^ply_usr_[0-9A-Z]{10,}$", assignee_user_id):
                e = _err("VALIDATION_ERROR", "Invalid assignee_user_id", field="assignee_user_id")
                _log("error", None, e["error"])
                return e

        if team_id is not None:
            if not isinstance(team_id, str) or not re.match(r"^ply_team_[0-9A-Z]{10,}$", team_id):
                e = _err("VALIDATION_ERROR", "Invalid team_id", field="team_id")
                _log("error", None, e["error"])
                return e

        if account_id is not None:
            if not isinstance(account_id, str) or not re.match(r"^(ply_acc|ply_con)_[0-9A-Z]{10,}$", account_id):
                e = _err("VALIDATION_ERROR", "Invalid account_id", field="account_id")
                _log("error", None, e["error"])
                return e

        if contact_id is not None:
            if not isinstance(contact_id, str) or not re.match(r"^(ply_acc|ply_con)_[0-9A-Z]{10,}$", contact_id):
                e = _err("VALIDATION_ERROR", "Invalid contact_id", field="contact_id")
                _log("error", None, e["error"])
                return e

        if ticket_form_id is not None:
            if not isinstance(ticket_form_id, str) or not re.match(r"^ply_form_[0-9A-Z]{10,}$", ticket_form_id):
                e = _err("VALIDATION_ERROR", "Invalid ticket_form_id", field="ticket_form_id")
                _log("error", None, e["error"])
                return e

        if tag_ids is not None:
            if not isinstance(tag_ids, list):
                e = _err("VALIDATION_ERROR", "tag_ids must be an array", field="tag_ids")
                _log("error", None, e["error"])
                return e
            for i, tid in enumerate(tag_ids):
                if not isinstance(tid, str) or not re.match(r"^ply_tag_[0-9A-Z]{10,}$", tid):
                    e = _err("VALIDATION_ERROR", "Invalid tag id", field="tag_ids", index=i)
                    _log("error", None, e["error"])
                    return e

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
            _log("error", None, e["error"])
            return e

        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "priority"):
            e = _err("VALIDATION_ERROR", "Invalid sort field", field="sort")
            _log("error", None, e["error"])
            return e

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "Invalid order", field="order")
            _log("error", None, e["error"])
            return e

        # Ambient auth: must have at least one user row in workspace
        users_teams = _load("users_teams.json")
        principal_user_id = None
        if isinstance(users_teams, list):
            for u in users_teams:
                if isinstance(u, dict) and u.get("team_type") == "user" and u.get("workspace_id") == workspace_id and u.get("user_status") in ("active", "invited"):
                    principal_user_id = u.get("user_id")
                    break
        if principal_user_id is None:
            e = _err("UNAUTHORIZED", "No valid authentication context for this workspace")
            _log("error", None, e["error"])
            return e

        workspaces = _load("workspaces.json")
        wsp = None
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("id") == workspace_id:
                    wsp = w
                    break
        if not wsp or wsp.get("status") == "deleted":
            e = _err("NOT_FOUND", "Workspace not found")
            _log("error", principal_user_id, e["error"])
            return e

        entities = _load("issues_messages_tags_forms.json")
        if not isinstance(entities, list):
            entities = []

        def _norm(s):
            return (s or "").strip().lower()

        qn = _norm(query) if query else None

        issues = []
        for r in entities:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("entity_type") != "issue":
                continue

            if status is not None:
                if r.get("status") != status:
                    continue
            else:
                # default exclude deleted
                if r.get("status") == "deleted":
                    continue

            if priority is not None and r.get("priority") != priority:
                continue
            if assignee_user_id is not None and r.get("assignee_user_id") != assignee_user_id:
                continue
            if team_id is not None and r.get("team_id") != team_id:
                continue
            if account_id is not None and r.get("account_id") != account_id:
                continue
            if contact_id is not None and r.get("contact_id") != contact_id:
                continue
            if ticket_form_id is not None and r.get("ticket_form_id") != ticket_form_id:
                continue

            if tag_ids is not None:
                row_tags = r.get("tag_ids")
                if not isinstance(row_tags, list):
                    continue
                # require all provided tags present
                if any(t not in row_tags for t in tag_ids):
                    continue

            if qn:
                hay = " ".join([_norm(r.get("title")), _norm(r.get("description"))])
                if qn not in hay:
                    continue

            issues.append(r)

        # Sorting
        reverse = (order == "desc")
        if sort in ("created_at", "updated_at"):
            issues.sort(key=lambda x: (x.get(sort) or ""), reverse=reverse)
        else:
            # priority sorting: low<medium<high<urgent
            pr_rank = {"low": 1, "medium": 2, "high": 3, "urgent": 4}
            issues.sort(key=lambda x: pr_rank.get(x.get("priority"), 0), reverse=reverse)

        # Cursor pagination: cursor is base64("offset:<n>")
        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
                _log("error", principal_user_id, e["error"])
                return e
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                raw_s = raw.decode("utf-8")
                if not raw_s.startswith("offset:"):
                    raise ValueError("bad cursor")
                offset = int(raw_s.split(":", 1)[1])
                if offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                e = _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
                _log("error", principal_user_id, e["error"])
                return e

        total = len(issues)
        page = issues[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

        resp = {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort": sort,
                "order": order
            }
        }
        _log("ok", principal_user_id, None)
        return resp
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", None, e["error"])
        return e

def pylon_create_issue(workspace_id, title, contact_id, description=None, status=None, priority=None, account_id=None, assignee_user_id=None, team_id=None, ticket_form_id=None, tag_ids=None, snoozed_until=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_create_issue"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save_logs(logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        raw = f"{ms}-{os.urandom(10).hex()}".encode("utf-8")
        h = hashlib.sha1(raw).digest()
        n = int.from_bytes(h, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    # Validate inputs
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(title, str) or title.strip() == "":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not isinstance(contact_id, str) or re.match(r"^(ply_acc|ply_con)_[0-9A-Z]{10,}$", contact_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_id is malformed")
    if description is not None and not isinstance(description, str):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string")
    allowed_status = ["open", "in_progress", "pending", "snoozed", "resolved", "closed", "deleted"]
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid")
    allowed_priority = ["low", "medium", "high", "urgent"]
    if priority is not None and (not isinstance(priority, str) or priority not in allowed_priority):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "priority is invalid")
    if account_id is not None and (not isinstance(account_id, str) or re.match(r"^(ply_acc|ply_con)_[0-9A-Z]{10,}$", account_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed")
    if assignee_user_id is not None and (not isinstance(assignee_user_id, str) or re.match(r"^ply_usr_[0-9A-Z]{10,}$", assignee_user_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assignee_user_id is malformed")
    if team_id is not None and (not isinstance(team_id, str) or re.match(r"^ply_team_[0-9A-Z]{10,}$", team_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "team_id is malformed")
    if ticket_form_id is not None and (not isinstance(ticket_form_id, str) or re.match(r"^ply_form_[0-9A-Z]{10,}$", ticket_form_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticket_form_id is malformed")
    if tag_ids is not None:
        if not isinstance(tag_ids, list) or any((not isinstance(x, str) or re.match(r"^ply_tag_[0-9A-Z]{10,}$", x) is None) for x in tag_ids):
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tag_ids must be an array of ply_tag_* ids")

    # Rate limit
    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # Workspace exists and active-ish (allow active/suspended; disallow deleted)
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    customers = _load("customers.json")
    if not isinstance(customers, list):
        customers = []
    issues = _load("issues_messages_tags_forms.json")
    if not isinstance(issues, list):
        issues = []
    users_teams = _load("users_teams.json")
    if not isinstance(users_teams, list):
        users_teams = []

    # Contact must exist, be contact type, same workspace, not deleted
    contact = next((c for c in customers if isinstance(c, dict) and c.get("id") == contact_id and c.get("workspace_id") == workspace_id), None)
    if not contact:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found")
    if contact.get("entity_type") != "contact":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_id must reference a contact customer record")
    if contact.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found")

    # Infer account if not provided
    inferred_account_id = contact.get("account_id")
    eff_account_id = account_id if account_id is not None else inferred_account_id

    # Validate account if set: must be an account type in same workspace, not deleted
    if eff_account_id is not None:
        acc = next((c for c in customers if isinstance(c, dict) and c.get("id") == eff_account_id and c.get("workspace_id") == workspace_id), None)
        if not acc:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Account not found")
        if acc.get("entity_type") != "account":
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id must reference an account customer record")
        if acc.get("status") == "deleted":
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Account not found")

    # Validate assignment references
    if assignee_user_id is not None:
        usr = next((u for u in users_teams if isinstance(u, dict) and u.get("user_id") == assignee_user_id and u.get("workspace_id") == workspace_id), None)
        if not usr:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Assignee user not found")
        if usr.get("team_type") != "user" or usr.get("user_status") != "active":
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assignee_user_id must reference an active user")
    if team_id is not None:
        team = next((u for u in users_teams if isinstance(u, dict) and u.get("team_id") == team_id and u.get("workspace_id") == workspace_id and u.get("team_type") == "team"), None)
        if not team:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Team not found")
        if team.get("team_status") != "active":
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_id must reference an active team")

    # Ticket form must exist if set
    if ticket_form_id is not None:
        form = next((e for e in issues if isinstance(e, dict) and e.get("id") == ticket_form_id and e.get("workspace_id") == workspace_id), None)
        if not form:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Ticket form not found")
        if form.get("entity_type") != "ticket_form" or form.get("status") != "active":
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ticket_form_id must reference an active ticket_form")

    # Tag ids must reference active tag rows
    eff_tag_ids = tag_ids if isinstance(tag_ids, list) else []
    if eff_tag_ids:
        tag_rows = {e.get("id"): e for e in issues if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "tag" and e.get("status") == "active"}
        missing = [tid for tid in eff_tag_ids if tid not in tag_rows]
        if missing:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "One or more tags not found", missing_tag_ids=missing)

    # Apply issue defaults (per business rules: create issue => status=open)
    if status is None:
        status = "open"
    if status != "open":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "On creation, issue status must be 'open'")
    if priority is None:
        priority = "medium"

    # Snoozed fields should not be set on create (since status must be open); but if provided, validate and ignore? Realistic: reject if snoozed_until provided without snoozed.
    if snoozed_until is not None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "snoozed_until can only be set when status='snoozed'")

    # Create issue row
    issue_row = {
        "id": _gen_ulid_like("ply_iss"),
        "workspace_id": workspace_id,
        "entity_type": "issue",
        "status": "open",
        "issue_id": None,
        "account_id": eff_account_id,
        "contact_id": contact_id,
        "title": title,
        "description": description,
        "priority": priority,
        "assignee_user_id": assignee_user_id,
        "team_id": team_id,
        "ticket_form_id": ticket_form_id,
        "tag_ids": eff_tag_ids,
        "snoozed_until": None,
        "message_direction": None,
        "sender_type": None,
        "sender_user_id": None,
        "sender_contact_id": None,
        "body": None,
        "tag_name": None,
        "tag_color": None,
        "form_name": None,
        "form_schema": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    issues.append(issue_row)
    try:
        _save("issues_messages_tags_forms.json", issues)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist issue")

    _append_log("success", None)
    return {"issue": issue_row}

def pylon_get_knowledge_bases(workspace_id, query=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log(endpoint, workspace_id, status_code, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(workspace_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("workspace_id") != workspace_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    def _quota_ok(workspace_id):
        wss = _load("workspaces.json")
        plan = None
        for w in wss:
            if w.get("id") == workspace_id:
                plan = w.get("plan")
                break
        daily = {"free": 2000, "pro": 10000, "business": 50000, "enterprise": 200000}.get(plan or "free", 2000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        day = now.date()
        cnt = 0
        for r in logs:
            if r.get("workspace_id") != workspace_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts:
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts.date() == day:
                    cnt += 1
        return cnt < daily

    endpoint = "pylon_get_knowledge_bases"

    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
        _ensure_request_log(endpoint, workspace_id if isinstance(workspace_id, str) else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not _rate_limit_ok(workspace_id):
        _ensure_request_log(endpoint, workspace_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if not _quota_ok(workspace_id):
        _ensure_request_log(endpoint, workspace_id, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    if query is not None and not isinstance(query, str):
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string.")
    if status is not None and (not isinstance(status, str) or status not in ["active", "archived", "deleted"]):
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ["created_at", "updated_at", "kb_name"]:
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ["asc", "desc"]:
        _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")

    # Ambient auth: ensure workspace exists and is accessible (not deleted)
    wss = _load("workspaces.json")
    ws = next((w for w in wss if w.get("id") == workspace_id and w.get("status") in ["active", "suspended"]), None)
    if not ws:
        _ensure_request_log(endpoint, workspace_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible workspace context found for this request.")

    rows = _load("knowledge_webhooks.json")
    if not isinstance(rows, list):
        rows = []

    kbs = [r for r in rows if r.get("workspace_id") == workspace_id and r.get("entity_type") == "knowledge_base"]
    # Business rule: return status in ['active','archived'] by default
    if status is None:
        kbs = [r for r in kbs if r.get("status") in ["active", "archived"]]
    else:
        kbs = [r for r in kbs if r.get("status") == status]

    if query:
        q = query.strip().lower()
        def _match(r):
            return (str(r.get("kb_name") or "").lower().find(q) >= 0) or (str(r.get("kb_description") or "").lower().find(q) >= 0)
        kbs = [r for r in kbs if _match(r)]

    # Article counts: count active articles per KB
    articles = [r for r in rows if r.get("workspace_id") == workspace_id and r.get("entity_type") == "knowledge_base_article" and r.get("status") == "active"]
    counts = {}
    for a in articles:
        kb_id = a.get("knowledge_base_id")
        if kb_id:
            counts[kb_id] = counts.get(kb_id, 0) + 1

    def _sort_key(r):
        if sort == "kb_name":
            return (str(r.get("kb_name") or "").lower(), r.get("id") or "")
        dt = _parse_dt(r.get(sort) or "")
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")

    reverse = (order == "desc")
    kbs.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cursor:
        try:
            start = int(base64.urlsafe_b64decode(cursor.encode("ascii") + b"===").decode("utf-8"))
            if start < 0:
                start = 0
        except Exception:
            _ensure_request_log(endpoint, workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
    total = len(kbs)
    page = kbs[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("ascii").rstrip("=")

    # Return with derived metadata
    out = []
    for r in page:
        rr = dict(r)
        rr["active_article_count"] = counts.get(r.get("id"), 0)
        out.append(rr)

    _ensure_request_log(endpoint, workspace_id, "OK")
    return {
        "knowledge_bases": out,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

