        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    allowed_sort = {"published_at", "created_at", "updated_at", "article_title"}
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid.", field="order")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # workspace exists & rate limit
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") in ("active", "suspended")), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "workspace_id not found.", field="workspace_id")

    if not _rate_limit_ok(workspace_id):
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

    kw = _load("knowledge_webhooks.json")
    if not isinstance(kw, list):
        kw = []

    # IMPORTANT: do NOT error just because this KB id isn't present in this workspace in the current dataset.
    # Real listing endpoints return empty lists for no matching rows; cross-workspace access is enforced by filtering.
    rows = [r for r in kw if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("entity_type") == "knowledge_base_article" and r.get("knowledge_base_id") == knowledge_base_id]

    # Exclude deleted unless explicitly requested
    if status is None:
        rows = [r for r in rows if r.get("status") != "deleted"]
    else:
        rows = [r for r in rows if r.get("status") == status]

    if author_user_id is not None:
        rows = [r for r in rows if r.get("author_user_id") == author_user_id]

    if published is True:
        rows = [r for r in rows if r.get("published_at") is not None]
    elif published is False:
        rows = [r for r in rows if r.get("published_at") is None]

    if query:
        q = query.strip().lower()
        def _txt(v):
            return v.lower() if isinstance(v, str) else ""
        rows = [r for r in rows if (q in _txt(r.get("article_title")) or q in _txt(r.get("article_body")) or q in _txt(r.get("article_slug")))]

    def _sort_key(r):
        if sort == "article_title":
            return (r.get("article_title") or "").lower()
        if sort in ("created_at", "updated_at", "published_at"):
            dt = _parse_dt(r.get(sort))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (r.get("updated_at") or "")

    reverse = (order == "desc")
    rows_sorted = sorted(rows, key=_sort_key, reverse=reverse)

    # Cursor is treated as "start after id" (opaque-ish); if not found, start at 0.
    start = 0
    if cursor:
        for i, r in enumerate(rows_sorted):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows_sorted[start:start + limit]
    has_more = start + limit < len(rows_sorted)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log("ok")
    return {
        "articles": page,
        "meta": {
            "total": len(rows_sorted),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

def pylon_create_knowledge_base_article(workspace_id, knowledge_base_id, article_title, article_body, article_slug=None, author_user_id=None, published_at=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_create_knowledge_base_article"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        raw = f"{ms}-{os.urandom(10).hex()}".encode("utf-8")
        h = hashlib.sha1(raw).digest()
        n = int.from_bytes(h, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    # Validate
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(knowledge_base_id, str) or re.match(r"^ply_kb_[0-9A-Z]{10,}$", knowledge_base_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "knowledge_base_id is malformed")
    if not isinstance(article_title, str) or article_title.strip() == "":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "article_title is required and must be a non-empty string")
    if not isinstance(article_body, str) or article_body.strip() == "":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "article_body is required and must be a non-empty string")
    if article_slug is not None and not isinstance(article_slug, str):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "article_slug must be a string")
    if author_user_id is not None and (not isinstance(author_user_id, str) or re.match(r"^ply_usr_[0-9A-Z]{10,}$", author_user_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "author_user_id is malformed")
    if status is not None and (not isinstance(status, str) or status not in ["active", "archived", "deleted"]):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid")
    pub_dt = None
    if published_at is not None:
        pub_dt = _parse_dt(published_at)
        if pub_dt is None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "published_at must be an ISO date-time")

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # Workspace existence
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    # Find KB row
    kbwh = _load("knowledge_webhooks.json")
    if not isinstance(kbwh, list):
        kbwh = []
    kb = next((r for r in kbwh if isinstance(r, dict) and r.get("id") == knowledge_base_id and r.get("workspace_id") == workspace_id), None)
    if not kb:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Knowledge base not found")
    if kb.get("entity_type") != "knowledge_base":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "knowledge_base_id must reference a knowledge_base record")
    if kb.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Knowledge base not found")

    # Resolve author: business rule says set to caller user; without explicit auth context in this offline store,
    # choose a valid active user in this workspace if not provided.
    users_teams = _load("users_teams.json")
    if not isinstance(users_teams, list):
        users_teams = []
    if author_user_id is None:
        u = next((x for x in users_teams if isinstance(x, dict) and x.get("workspace_id") == workspace_id and x.get("team_type") == "user" and x.get("user_status") == "active"), None)
        if u is None:
            _append_log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active user context available for author_user_id in this workspace")
        author_user_id = u.get("user_id")
    else:
        u = next((x for x in users_teams if isinstance(x, dict) and x.get("workspace_id") == workspace_id and x.get("user_id") == author_user_id and x.get("team_type") == "user"), None)
        if not u:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Author user not found")

    # Defaults
    if status is None:
        status = "active"

    # Unique slug within KB among non-deleted
    eff_slug = article_slug.strip() if isinstance(article_slug, str) and article_slug.strip() != "" else None
    if eff_slug is None:
        # generate from title
        slug = re.sub(r"[^a-zA-Z0-9]+", "-", article_title.strip().lower()).strip("-")
        eff_slug = slug if slug else f"article-{int(time.time())}"
    for r in kbwh:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("entity_type") != "knowledge_base_article":
            continue
        if r.get("knowledge_base_id") != knowledge_base_id:
            continue
        if r.get("status") == "deleted":
            continue
        if r.get("article_slug") == eff_slug:
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "article_slug must be unique within the knowledge base")

    article_row = {
        "id": _gen_ulid_like("ply_art"),
        "workspace_id": workspace_id,
        "entity_type": "knowledge_base_article",
        "status": status,
        "knowledge_base_id": knowledge_base_id,
        "kb_name": None,
        "kb_description": None,
        "article_title": article_title,
        "article_body": article_body,
        "article_slug": eff_slug,
        "published_at": pub_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z") if pub_dt else None,
        "author_user_id": author_user_id,
        "webhook_url": None,
        "webhook_secret": None,
        "event_types": None,
        "last_delivery_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    kbwh.append(article_row)
    try:
        _save("knowledge_webhooks.json", kbwh)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist article")

    _append_log("success", None)
    return {"article": article_row}

def pylon_get_teams(workspace_id, status=None, specialization=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_get_teams"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, credential_id, http_status, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ply_req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "http_status": http_status,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if obj.get("v") != 1 or obj.get("endpoint") != endpoint:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = {"v": 1, "endpoint": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Resolve workspace context (ambient auth): must exist and be active/suspended (not deleted)
    wss = _load("workspaces.json")
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not isinstance(workspace_id, str) or not __import__("re").match(r"^ply_wsp_[0-9A-Z]{4,}$", workspace_id):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not ws:
        _log("error", None, 404, "NOT_FOUND", "Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", None, 401, "UNAUTHORIZED", "Workspace is deleted.")
        return _err("UNAUTHORIZED", "Workspace is deleted.")

    # Rate-limit / quota enforcement if present
    usage = _load("usage_counters.json")
    plans = {"free": {"rpm": 120, "rpd": 5000}, "pro": {"rpm": 600, "rpd": 50000}, "business": {"rpm": 1200, "rpd": 200000}, "enterprise": {"rpm": 6000, "rpd": 2000000}}
    plan = ws.get("plan") if ws.get("plan") in plans else "free"
    limits = plans[plan]
    now = datetime.datetime.utcnow()
    minute_key = now.strftime("%Y%m%d%H%M")
    day_key = now.strftime("%Y%m%d")
    u = next((x for x in usage if isinstance(x, dict) and x.get("workspace_id") == workspace_id), None)
    if not u:
        u = {"workspace_id": workspace_id, "by_minute": {}, "by_day": {}}
        usage.append(u)
    by_min = u.setdefault("by_minute", {})
    by_day = u.setdefault("by_day", {})
    mcount = int(by_min.get(minute_key, 0))
    dcount = int(by_day.get(day_key, 0))
    if mcount >= limits["rpm"]:
        _log("error", None, 429, "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limits["rpm"], window="minute")
    if dcount >= limits["rpd"]:
        _log("error", None, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=limits["rpd"], window="day")

    # Validate filters/pagination
    if status is not None and status not in ("active", "archived"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid status filter.")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if specialization is not None and not isinstance(specialization, str):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid specialization filter.")
        return _err("VALIDATION_ERROR", "Invalid specialization filter.", field="specialization")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
    if sort is None:
        sort = "team_name"
    if sort not in ("team_name", "created_at", "updated_at"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid sort.")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid order.")
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")
    offset = _decode_cursor(cursor)
    if offset is None:
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Query teams stored in users_teams.json with team_type='team'
    ut = _load("users_teams.json")
    teams = []
    for r in ut:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("team_type") != "team":
            continue
        if r.get("team_status") not in ("active", "archived"):
            continue
        if status is not None and r.get("team_status") != status:
            continue
        if specialization is not None and r.get("specialization") != specialization:
            continue

        mem = r.get("team_memberships") if isinstance(r.get("team_memberships"), list) else []
        # Count members that reference active user rows in same workspace
        active_users = {u.get("user_id") for u in ut if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("team_type") == "user" and u.get("user_status") == "active"}
        member_count = 0
        for m in mem:
            if isinstance(m, dict) and m.get("member_user_id") in active_users:
                member_count += 1

        teams.append({
            "team_id": r.get("team_id") or r.get("user_id") or r.get("id"),
            "team_name": r.get("team_name"),
            "team_status": r.get("team_status"),
            "specialization": r.get("specialization"),
            "member_count": member_count,
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    # Sort
    def _key(x):
        if sort == "team_name":
            return (x.get("team_name") or "").lower()
        dt = _parse_dt(x.get(sort))
        return dt or datetime.datetime.min

    reverse = (order == "desc")
    teams.sort(key=_key, reverse=reverse)

    total = len(teams)
    page = teams[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    # persist usage and logs
    by_min[minute_key] = mcount + 1
    by_day[day_key] = dcount + 1
    _save("usage_counters.json", usage)
    _log("ok", None, 200)

    return {"teams": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

