    # Rate-limit / quota if present
    usage = _load("usage_counters.json")
    plans = {"free": {"rpm": 120, "rpd": 5000}, "pro": {"rpm": 600, "rpd": 50000}, "business": {"rpm": 1200, "rpd": 200000}, "enterprise": {"rpm": 6000, "rpd": 2000000}}
    plan = ws.get("plan") if ws.get("plan") in plans else "free"
    limits = plans[plan]
    now = datetime.datetime.utcnow()
    minute_key = now.strftime("%Y%m%d%H%M")
    day_key = now.strftime("%Y%m%d")
    u = next((x for x in usage if isinstance(x, dict) and x.get("workspace_id") == workspace_id), None)
    if not u:
        u = {"workspace_id": workspace_id, "by_minute": {}, "by_day": {}}
        usage.append(u)
    by_min = u.setdefault("by_minute", {})
    by_day = u.setdefault("by_day", {})
    mcount = int(by_min.get(minute_key, 0))
    dcount = int(by_day.get(day_key, 0))
    if mcount >= limits["rpm"]:
        _log("error", None, 429, "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limits["rpm"], window="minute")
    if dcount >= limits["rpd"]:
        _log("error", None, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=limits["rpd"], window="day")

    ut = _load("users_teams.json")
    team_row = None
    for r in ut:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("team_type") != "team":
            continue
        rid = r.get("team_id") or r.get("user_id") or r.get("id")
        if rid == team_id:
            team_row = r
            break
    if not team_row:
        by_min[minute_key] = mcount + 1
        by_day[day_key] = dcount + 1
        _save("usage_counters.json", usage)
        _log("error", None, 404, "NOT_FOUND", "Team not found.")
        return _err("NOT_FOUND", "Team not found.")

    # Expand members (must reference active users in same workspace)
    user_index = {}
    for r in ut:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("team_type") == "user":
            user_index[r.get("user_id")] = r

    members = []
    memberships = team_row.get("team_memberships") if isinstance(team_row.get("team_memberships"), list) else []
    for m in memberships:
        if not isinstance(m, dict):
            continue
        uid = m.get("member_user_id")
        urow = user_index.get(uid)
        if not urow or urow.get("user_status") != "active":
            continue
        members.append({
            "user_id": uid,
            "full_name": urow.get("full_name"),
            "email": urow.get("email"),
            "user_role": urow.get("user_role"),
            "availability_status": urow.get("availability_status"),
            "member_role": m.get("role"),
            "added_at": m.get("added_at"),
        })

    # Sort members by name then email for stable output
    members.sort(key=lambda x: ((x.get("full_name") or "").lower(), (x.get("email") or "").lower()))

    # Lightweight placeholders for "workload/metrics" (cannot fabricate; derive what we can)
    imtf = _load("issues_messages_tags_forms.json")
    open_statuses = {"open", "in_progress", "pending", "snoozed", "resolved"}
    team_issue_count = 0
    for r in imtf:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id or r.get("entity_type") != "issue":
            continue
        if r.get("team_id") != team_id:
            continue
        if r.get("status") in open_statuses:
            team_issue_count += 1

    result = {
        "team": {
            "team_id": team_id,
            "workspace_id": workspace_id,
            "team_name": team_row.get("team_name"),
            "team_status": team_row.get("team_status"),
            "specialization": team_row.get("specialization"),
            "created_at": team_row.get("created_at"),
            "updated_at": team_row.get("updated_at"),
            "member_count": len(members),
        },
        "members": members,
        "metrics": {
            "open_issue_count": team_issue_count
        }
    }

    by_min[minute_key] = mcount + 1
    by_day[day_key] = dcount + 1
    _save("usage_counters.json", usage)
    _log("ok", None, 200)
    return result

def pylon_create_team(workspace_id, team_name, specialization=None, team_status=None, **_extra):
    import json, os, datetime, time, re, secrets, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_create_team"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id, http_status, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ply_req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "http_status": http_status,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{4,}$", workspace_id):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
    if not isinstance(team_name, str) or not team_name.strip():
        _log("error", None, 400, "VALIDATION_ERROR", "team_name is required.")
        return _err("VALIDATION_ERROR", "team_name is required.", field="team_name")
    if specialization is not None and not isinstance(specialization, str):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid specialization.")
        return _err("VALIDATION_ERROR", "Invalid specialization.", field="specialization")
    if team_status is None:
        team_status = "active"
    if team_status not in ("active", "archived"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid team_status.")
        return _err("VALIDATION_ERROR", "Invalid team_status.", field="team_status")

    # Workspace must exist
    wss = _load("workspaces.json")
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", None, 404, "NOT_FOUND", "Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", None, 401, "UNAUTHORIZED", "Workspace is deleted.")
        return _err("UNAUTHORIZED", "Workspace is deleted.")

    # Rate-limit / quota if present
    usage = _load("usage_counters.json")
    plans = {"free": {"rpm": 120, "rpd": 5000}, "pro": {"rpm": 600, "rpd": 50000}, "business": {"rpm": 1200, "rpd": 200000}, "enterprise": {"rpm": 6000, "rpd": 2000000}}
    plan = ws.get("plan") if ws.get("plan") in plans else "free"
    limits = plans[plan]
    now = datetime.datetime.utcnow()
    minute_key = now.strftime("%Y%m%d%H%M")
    day_key = now.strftime("%Y%m%d")
    u = next((x for x in usage if isinstance(x, dict) and x.get("workspace_id") == workspace_id), None)
    if not u:
        u = {"workspace_id": workspace_id, "by_minute": {}, "by_day": {}}
        usage.append(u)
    by_min = u.setdefault("by_minute", {})
    by_day = u.setdefault("by_day", {})
    mcount = int(by_min.get(minute_key, 0))
    dcount = int(by_day.get(day_key, 0))
    if mcount >= limits["rpm"]:
        _log("error", None, 429, "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limits["rpm"], window="minute")
    if dcount >= limits["rpd"]:
        _log("error", None, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=limits["rpd"], window="day")

    # Authorization: schema doesn't include tokens/roles; treat as ambient authenticated.
    # But if workspace suspended/deleted could be restricted. We'll allow for suspended, deny for deleted (handled above).

    ut = _load("users_teams.json")

    # Conflict: unique(workspace_id, team_name) WHERE team_type='team' AND team_status='active'
    # Tool says "same name already exists" (we treat active teams as conflicting; archived can be recreated).
    for r in ut:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("team_type") != "team":
            continue
        if (r.get("team_name") or "").strip().lower() == team_name.strip().lower() and r.get("team_status") == "active":
            by_min[minute_key] = mcount + 1
            by_day[day_key] = dcount + 1
            _save("usage_counters.json", usage)
            _log("error", None, 409, "CONFLICT", "A team with this name already exists.")
            return _err("CONFLICT", "A team with this name already exists.", field="team_name")

    # Generate team id
    alphabet = string.ascii_uppercase + string.digits
    def _new_team_id():
        return "ply_team_" + "".join(secrets.choice(alphabet) for _ in range(10))

    existing_ids = {r.get("team_id") or r.get("user_id") or r.get("id") for r in ut if isinstance(r, dict)}
    tid = _new_team_id()
    while tid in existing_ids:
        tid = _new_team_id()

    now_iso = _now_iso()
    team_row = {
        "user_id": tid,  # primary_key is user_id in this mixed collection
        "workspace_id": workspace_id,
        "email": None,
        "full_name": None,
        "user_role": None,
        "availability_status": None,
        "user_status": None,
        "team_id": tid,
        "team_name": team_name.strip(),
        "team_type": "team",
        "team_status": team_status,
        "specialization": specialization,
        "team_memberships": [],
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    ut.append(team_row)
    _save("users_teams.json", ut)

    by_min[minute_key] = mcount + 1
    by_day[day_key] = dcount + 1
    _save("usage_counters.json", usage)
    _log("ok", None, 201)

    return {
        "team": {
            "team_id": tid,
            "workspace_id": workspace_id,
            "team_name": team_row["team_name"],
            "team_status": team_row["team_status"],
            "specialization": team_row.get("specialization"),
            "member_count": 0,
            "created_at": team_row["created_at"],
            "updated_at": team_row["updated_at"],
        }
    }

def pylon_get_accounts(workspace_id, status=None, subscription_level=None, billing_status=None, company_name=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_get_accounts"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, credential_id, http_status, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ply_req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "http_status": http_status,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if obj.get("v") != 1 or obj.get("endpoint") != endpoint:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = {"v": 1, "endpoint": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Validate workspace_id
    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{4,}$", workspace_id):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")

    # Workspace existence
    wss = _load("workspaces.json")
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", None, 404, "NOT_FOUND", "Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", None, 401, "UNAUTHORIZED", "Workspace is deleted.")
        return _err("UNAUTHORIZED", "Workspace is deleted.")

    # Rate-limit / quota if present
    usage = _load("usage_counters.json")
    plans = {"free": {"rpm": 120, "rpd": 5000}, "pro": {"rpm": 600, "rpd": 50000}, "business": {"rpm": 1200, "rpd": 200000}, "enterprise": {"rpm": 6000, "rpd": 2000000}}
    plan = ws.get("plan") if ws.get("plan") in plans else "free"
    limits = plans[plan]
    now = datetime.datetime.utcnow()
    minute_key = now.strftime("%Y%m%d%H%M")
    day_key = now.strftime("%Y%m%d")
    u = next((x for x in usage if isinstance(x, dict) and x.get("workspace_id") == workspace_id), None)
    if not u:
        u = {"workspace_id": workspace_id, "by_minute": {}, "by_day": {}}
        usage.append(u)
    by_min = u.setdefault("by_minute", {})
    by_day = u.setdefault("by_day", {})
    mcount = int(by_min.get(minute_key, 0))
    dcount = int(by_day.get(day_key, 0))
    if mcount >= limits["rpm"]:
        _log("error", None, 429, "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limits["rpm"], window="minute")
    if dcount >= limits["rpd"]:
        _log("error", None, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=limits["rpd"], window="day")

    # Validate filters
    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid status filter.")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if subscription_level is not None and subscription_level not in ("trial", "free", "starter", "pro", "enterprise"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid subscription_level filter.")
        return _err("VALIDATION_ERROR", "Invalid subscription_level filter.", field="subscription_level")
    if billing_status is not None and billing_status not in ("current", "past_due", "canceled"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid billing_status filter.")
        return _err("VALIDATION_ERROR", "Invalid billing_status filter.", field="billing_status")
    if company_name is not None and not isinstance(company_name, str):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid company_name filter.")
        return _err("VALIDATION_ERROR", "Invalid company_name filter.", field="company_name")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
    if sort is None:
        sort = "company_name"
    if sort not in ("company_name", "created_at", "updated_at"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid sort.")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid order.")
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")
    offset = _decode_cursor(cursor)
    if offset is None:
        _log("error", None, 400, "VALIDATION_ERROR", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Base selection: entity_type='account' and status != 'deleted' (business rule)
    customers = _load("customers.json")
    rows = []
    for r in customers:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("entity_type") != "account":
            continue
        if r.get("status") == "deleted":
            continue

        # Filters
        if status is not None:
            # requested 'deleted' should return empty due to base rule; we allow but it will filter out.
            if r.get("status") != status:
                continue
        if subscription_level is not None and r.get("subscription_level") != subscription_level:
            continue
        if billing_status is not None and r.get("billing_status") != billing_status:
            continue
        if company_name is not None and r.get("company_name") != company_name:
            continue

        rows.append(r)

    # Sort
    def _key(r):
        if sort == "company_name":
            return (r.get("company_name") or "").lower()
        dt = _parse_dt(r.get(sort))
        return dt or datetime.datetime.min

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    by_min[minute_key] = mcount + 1
    by_day[day_key] = dcount + 1
    _save("usage_counters.json", usage)
    _log("ok", None, 200)

    return {"accounts": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def pylon_get_account(workspace_id, account_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_get_account"

    # --- validations ---
    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{4,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(account_id, str) or not re.match(r"^ply_acc_[0-9A-Z]{4,}$", account_id):
        return _err("VALIDATION_ERROR", "Invalid account_id.")

    workspaces = _load("workspaces.json")
    customers = _load("customers.json")
    issues = _load("issues_messages_tags_forms.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")

    # Ambient auth context: permit only if there's at least one user in this workspace (represents authenticated access).
    users_teams = _load("users_teams.json")
    if not any(r.get("workspace_id") == workspace_id and r.get("team_type") == "user" for r in users_teams):
        return _err("UNAUTHORIZED", "No authenticated context available for this workspace.")

    # Scope: enforce workspace boundary.
    acct = next((c for c in customers if c.get("workspace_id") == workspace_id and c.get("id") == account_id and c.get("entity_type") == "account"), None)
    if not acct or acct.get("status") == "deleted":
        return _err("NOT_FOUND", "Account not found in workspace.")

    related_contacts = [
        c for c in customers
        if c.get("workspace_id") == workspace_id
        and c.get("entity_type") == "contact"
        and c.get("account_id") == account_id
        and c.get("status") != "deleted"
    ]

    related_issues = [
        i for i in issues
        if i.get("workspace_id") == workspace_id
        and i.get("entity_type") == "issue"
        and i.get("account_id") == account_id
        and i.get("status") != "deleted"
    ]

    # record request dynamics if request_log exists
    reqlog = _load("request_log.json")
    if isinstance(reqlog, list):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": "ok",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_log.json", reqlog)

    return {
        "account": acct,
        "contacts": related_contacts,
        "issues": related_issues
    }

