            _log(404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "ticket_form_id not found in workspace.")

    # Tag existence check (only active tags are valid per schema rule for tag_ids[])
    if tag_ids:
        active_tags = {r.get("id") for r in rows if r.get("workspace_id") == workspace_id and r.get("entity_type") == "tag" and r.get("status") == "active"}
        missing = [t for t in tag_ids if t not in active_tags]
        if missing:
            _log(404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "One or more tag_ids not found as active tags in workspace.", missing_tag_ids=missing)

    # cursor decode (offset-based opaque cursor)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("bad cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Build message text index per issue only if query present
    q = query.strip().lower() if isinstance(query, str) else None
    msg_bodies_by_issue = {}
    if q:
        for r in rows:
            if r.get("workspace_id") != workspace_id or r.get("entity_type") != "message":
                continue
            iid = r.get("issue_id")
            body = r.get("body")
            if isinstance(iid, str) and isinstance(body, str):
                msg_bodies_by_issue.setdefault(iid, []).append(body.lower())

    def _match_issue(issue):
        if issue.get("workspace_id") != workspace_id:  # enforced scoping
            return False
        if issue.get("entity_type") != "issue":
            return False
        if status is not None and issue.get("status") != status:
            return False
        if priority is not None and issue.get("priority") != priority:
            return False
        if assignee_user_id is not None and issue.get("assignee_user_id") != assignee_user_id:
            return False
        if team_id is not None and issue.get("team_id") != team_id:
            return False
        if account_id is not None and issue.get("account_id") != account_id:
            return False
        if contact_id is not None and issue.get("contact_id") != contact_id:
            return False
        if ticket_form_id is not None and issue.get("ticket_form_id") != ticket_form_id:
            return False
        if tag_ids is not None:
            issue_tags = issue.get("tag_ids") or []
            if not isinstance(issue_tags, list):
                return False
            # require all specified tags
            for t in tag_ids:
                if t not in issue_tags:
                    return False
        if q:
            title = issue.get("title") or ""
            desc = issue.get("description") or ""
            text = (str(title) + "\n" + str(desc)).lower()
            if q in text:
                return True
            # search messages
            bodies = msg_bodies_by_issue.get(issue.get("id"), [])
            return any(q in b for b in bodies)
        return True

    issues = [r for r in rows if _match_issue(r)]

    # sort
    sort_field = sort or "updated_at"
    sort_order = order or "desc"

    pr_rank = {"low": 1, "medium": 2, "high": 3, "urgent": 4}
    def _dt_key(v):
        dt = _parse_dt(v) if isinstance(v, str) else None
        return dt if dt is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if sort_field in {"created_at","updated_at"}:
        issues.sort(key=lambda x: _dt_key(x.get(sort_field)), reverse=(sort_order == "desc"))
    elif sort_field == "priority":
        issues.sort(key=lambda x: pr_rank.get(x.get("priority"), 0), reverse=(sort_order == "desc"))

    total = len(issues)
    page = issues[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"off:{next_offset}".encode("utf-8")).decode("utf-8") if has_more else None

    _log(200)
    return {
        "issues": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort_field,
            "order": sort_order
        }
    }

def pylon_get_issue(workspace_id, issue_id, include_messages=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "pylon_get_issue",
                "workspace_id": workspace_id,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(issue_id, str) or re.match(r"^ply_iss_[0-9A-Z]{10,}$", issue_id) is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid issue_id.")
    if include_messages is None:
        include_messages = True
    if not isinstance(include_messages, bool):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_messages must be a boolean.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if ws is None:
        _log(401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible active workspace for this request.")

    rows = _load("issues_messages_tags_forms.json")
    customers = _load("customers.json")

    issue = next((r for r in rows if r.get("id") == issue_id and r.get("workspace_id") == workspace_id and r.get("entity_type") == "issue"), None)
    if issue is None:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.")

    account = None
    contact = None
    if isinstance(issue.get("account_id"), str):
        account = next((c for c in customers if c.get("id") == issue.get("account_id") and c.get("workspace_id") == workspace_id and c.get("entity_type") == "account" and c.get("status") != "deleted"), None)
    if isinstance(issue.get("contact_id"), str):
        contact = next((c for c in customers if c.get("id") == issue.get("contact_id") and c.get("workspace_id") == workspace_id and c.get("entity_type") == "contact" and c.get("status") != "deleted"), None)

    resp = {
        "issue": issue,
        "account": account,
        "contact": contact
    }

    if include_messages:
        msgs = [r for r in rows if r.get("workspace_id") == workspace_id and r.get("entity_type") == "message" and r.get("issue_id") == issue_id]
        # order by created_at asc
        def _dt(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                if isinstance(s, str):
                    dt = datetime.datetime.fromisoformat(s)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt.astimezone(datetime.timezone.utc)
            except Exception:
                pass
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        msgs.sort(key=lambda m: _dt(m.get("created_at")))
        resp["messages"] = msgs

    _log(200)
    return resp

def pylon_update_issue(workspace_id, issue_id, body, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_update_issue"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    # Validate
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(issue_id, str) or re.match(r"^ply_iss_[0-9A-Z]{10,}$", issue_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue_id is malformed")
    if not isinstance(body, dict):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object")

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    entities = _load("issues_messages_tags_forms.json")
    if not isinstance(entities, list):
        entities = []

    idx = None
    issue = None
    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == issue_id and e.get("workspace_id") == workspace_id:
            idx = i
            issue = e
            break
    if issue is None:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found")
    if issue.get("entity_type") != "issue":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue_id must reference an issue")

    # Allowed updates
    allowed_status = ["open", "in_progress", "pending", "snoozed", "resolved", "closed", "deleted"]
    allowed_priority = ["low", "medium", "high", "urgent"]

    # Validate referenced collections
    customers = _load("customers.json")
    if not isinstance(customers, list):
        customers = []
    users_teams = _load("users_teams.json")
    if not isinstance(users_teams, list):
        users_teams = []

    # Status transition enforcement
    transitions = {
        "open": ["in_progress", "pending", "snoozed", "resolved", "closed", "deleted"],
        "in_progress": ["pending", "snoozed", "resolved", "closed", "deleted"],
        "pending": ["in_progress", "snoozed", "resolved", "closed", "deleted"],
        "snoozed": ["open", "in_progress", "pending", "resolved", "closed", "deleted"],
        "resolved": ["closed", "in_progress", "deleted"],
        "closed": ["in_progress", "deleted"],
        "deleted": []
    }

    updates = {}
    for k in ["title", "description"]:
        if k in body:
            if body[k] is not None and not isinstance(body[k], str):
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{k} must be a string")
            updates[k] = body[k]
    if "priority" in body:
        pr = body["priority"]
        if pr is not None and (not isinstance(pr, str) or pr not in allowed_priority):
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority is invalid")
        updates["priority"] = pr
    if "assignee_user_id" in body:
        v = body["assignee_user_id"]
        if v is not None:
            if not isinstance(v, str) or re.match(r"^ply_usr_[0-9A-Z]{10,}$", v) is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "assignee_user_id is malformed")
            usr = next((u for u in users_teams if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("user_id") == v), None)
            if not usr:
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Assignee user not found")
            if usr.get("team_type") != "user" or usr.get("user_status") != "active":
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "assignee_user_id must reference an active user")
        updates["assignee_user_id"] = v
    if "team_id" in body:
        v = body["team_id"]
        if v is not None:
            if not isinstance(v, str) or re.match(r"^ply_team_[0-9A-Z]{10,}$", v) is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "team_id is malformed")
            team = next((u for u in users_teams if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("team_type") == "team" and u.get("team_id") == v), None)
            if not team:
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Team not found")
            if team.get("team_status") != "active":
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "team_id must reference an active team")
        updates["team_id"] = v

    if "account_id" in body:
        v = body["account_id"]
        if v is not None:
            if not isinstance(v, str) or re.match(r"^ply_acc_[0-9A-Z]{10,}$", v) is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "account_id is malformed")
            acc = next((c for c in customers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("id") == v), None)
            if not acc or acc.get("entity_type") != "account" or acc.get("status") == "deleted":
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Account not found")
        updates["account_id"] = v

    if "contact_id" in body:
        v = body["contact_id"]
        if v is not None:
            if not isinstance(v, str) or re.match(r"^ply_con_[0-9A-Z]{10,}$", v) is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "contact_id is malformed")
            con = next((c for c in customers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("id") == v), None)
            if not con or con.get("entity_type") != "contact" or con.get("status") == "deleted":
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Contact not found")
        updates["contact_id"] = v

    if "ticket_form_id" in body:
        v = body["ticket_form_id"]
        if v is not None:
            if not isinstance(v, str) or re.match(r"^ply_form_[0-9A-Z]{10,}$", v) is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "ticket_form_id is malformed")
            form = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("id") == v), None)
            if not form:
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Ticket form not found")
            if form.get("entity_type") != "ticket_form" or form.get("status") != "active":
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "ticket_form_id must reference an active ticket_form")
        updates["ticket_form_id"] = v

    if "tag_ids" in body:
        v = body["tag_ids"]
        if v is not None:
            if not isinstance(v, list) or any((not isinstance(x, str) or re.match(r"^ply_tag_[0-9A-Z]{10,}$", x) is None) for x in v):
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "tag_ids must be an array of ply_tag_* ids")
            tag_rows = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "tag" and e.get("status") == "active"}
            missing = [tid for tid in v if tid not in tag_rows]
            if missing:
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "One or more tags not found", missing_tag_ids=missing)
        updates["tag_ids"] = v if v is not None else []

    new_status = body.get("status") if "status" in body else None
    if new_status is not None:
        if not isinstance(new_status, str) or new_status not in allowed_status:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid")
        cur = issue.get("status")
        if cur not in transitions:
            _append_log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current issue status is invalid")
        if new_status != cur and new_status not in transitions.get(cur, []):
            _append_log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition issue from {cur} to {new_status}")

        if new_status == "snoozed":
            su = body.get("snoozed_until")
            su_dt = _parse_dt(su)
            if su_dt is None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "snoozed_until must be provided when status='snoozed' and be a valid ISO date-time")
            if su_dt <= now_dt:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "snoozed_until must be in the future")
            updates["snoozed_until"] = su_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        else:
            # If moving away from snoozed, clear snoozed_until unless explicitly provided (but it's not valid without snoozed)
            if "snoozed_until" in body and body.get("snoozed_until") is not None:
                _append_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "snoozed_until can only be set when status='snoozed'")
            if issue.get("status") == "snoozed":
                updates["snoozed_until"] = None

        updates["status"] = new_status
    else:
        # If snoozed_until given without status=snoozed -> reject
        if "snoozed_until" in body and body.get("snoozed_until") is not None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "snoozed_until can only be set when status='snoozed'")

    if not updates:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    # Apply update
    updated = dict(issue)
    for k, v in updates.items():
        updated[k] = v
    updated["updated_at"] = now_iso
    entities[idx] = updated

    try:
        _save("issues_messages_tags_forms.json", entities)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist issue update")

    _append_log("success", None)
    return {"issue": updated}

def pylon_snooze_issue(workspace_id, issue_id, snoozed_until, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_code, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "pylon_snooze_issue",
                "workspace_id": workspace_id,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(issue_id, str) or re.match(r"^ply_iss_[0-9A-Z]{10,}$", issue_id) is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid issue_id.")
    su_dt = _parse_dt(snoozed_until)
    if su_dt is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "snoozed_until must be an RFC3339 datetime string.")
    if su_dt <= now_dt:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "snoozed_until must be in the future.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if ws is None:
        _log(401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible active workspace for this request.")

    rows = _load("issues_messages_tags_forms.json")
    idx = next((i for i, r in enumerate(rows) if r.get("id") == issue_id and r.get("workspace_id") == workspace_id and r.get("entity_type") == "issue"), None)
    if idx is None:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.")

    issue = rows[idx]
    if issue.get("status") in {"closed", "deleted"}:
        _log(409, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot snooze an issue in status '{issue.get('status')}'.")

    # enforce transition validity per lifecycle rules: from current -> snoozed must be allowed
    transitions = {
        "open": ["in_progress", "pending", "snoozed", "resolved", "closed", "deleted"],
        "in_progress": ["pending", "snoozed", "resolved", "closed", "deleted"],
        "pending": ["in_progress", "snoozed", "resolved", "closed", "deleted"],
        "snoozed": ["open", "in_progress", "pending", "resolved", "closed", "deleted"],
        "resolved": ["closed", "in_progress", "deleted"],
        "closed": ["in_progress", "deleted"],
        "deleted": []
    }
    cur = issue.get("status")
    if cur != "snoozed" and "snoozed" not in transitions.get(cur, []):
        _log(409, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition issue status from {cur} to snoozed.")

    # idempotent if already snoozed with same until
    if issue.get("status") == "snoozed" and issue.get("snoozed_until") == snoozed_until:
        _log(200)
        return {"issue": issue}

    issue["status"] = "snoozed"
    issue["snoozed_until"] = snoozed_until
    issue["updated_at"] = now
    rows[idx] = issue
    try:
        _save("issues_messages_tags_forms.json", rows)
    except Exception:
        _log(500, error_code="CONFLICT")
        return _err("CONFLICT", "Failed to persist snooze update.")

    _log(200)
    return {"issue": issue}

def pylon_get_issue_messages(workspace_id, issue_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")

    def _load(n):
