        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_get_issue_messages"
    status_code = "ok"

    def _log_request(cred, status, latency_ms):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
                "timestamp": now,
                "endpoint": endpoint,
                "credential_id": cred,
                "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
                "status": status,
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _encode_cursor(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    # ---- validation ----
    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "workspace_id is invalid.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    if not isinstance(issue_id, str) or not re.match(r"^ply_iss_[0-9A-Z]{10,}$", issue_id):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "issue_id is invalid.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at",):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "sort must be 'created_at'.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    if cursor is not None and not isinstance(cursor, str):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    # ---- ambient auth / workspace scoping ----
    # Resolve a workspace visible to caller. With no explicit credentials in params, accept the workspace if it exists and active/suspended.
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") in ("active", "suspended")), None)
    if not wsp:
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Workspace not found.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    entities = _load("issues_messages_tags_forms.json")

    issue = next(
        (
            r
            for r in entities
            if r.get("id") == issue_id
            and r.get("workspace_id") == workspace_id
            and r.get("entity_type") == "issue"
        ),
        None,
    )
    if not issue:
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Issue not found.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    msgs = [
        r
        for r in entities
        if r.get("workspace_id") == workspace_id
        and r.get("entity_type") == "message"
        and r.get("issue_id") == issue_id
    ]

    # Sort by created_at (default), stable tie-break by id
    def _key(r):
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    reverse = order == "desc"
    msgs.sort(key=_key, reverse=reverse)

    cur = _decode_cursor(cursor)
    start = 0
    if cur:
        if cur.get("workspace_id") != workspace_id or cur.get("issue_id") != issue_id or cur.get("sort") != sort or cur.get("order") != order:
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "cursor is invalid for this request.")
            _log_request(None, status_code, int((time.time() - t0) * 1000))
            return resp
        # cursor payload stores last seen sort tuple
        last_created_at = _parse_dt(cur.get("last_created_at"))
        last_id = cur.get("last_id")
        if last_created_at is None or not isinstance(last_id, str):
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log_request(None, status_code, int((time.time() - t0) * 1000))
            return resp

        # Find the index after the last seen item, based on ordering
        def _after(r):
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            if not reverse:
                return (rdt, rid) > (last_created_at, last_id)
            else:
                return (rdt, rid) < (last_created_at, last_id)

        for i, r in enumerate(msgs):
            if _after(r):
                start = i
                break
        else:
            start = len(msgs)

    page = msgs[start : start + limit]
    has_more = start + limit < len(msgs)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        next_cursor = _encode_cursor(
            {
                "workspace_id": workspace_id,
                "issue_id": issue_id,
                "sort": sort,
                "order": order,
                "last_created_at": last_dt.isoformat(),
                "last_id": str(last.get("id") or ""),
            }
        )

    resp = {
        "object": "list",
        "data": page,
        "total": len(msgs),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    _log_request(None, status_code, int((time.time() - t0) * 1000))
    return resp

def pylon_create_issue_message(workspace_id, issue_id, body, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_create_issue_message"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        raw = f"{ms}-{os.urandom(10).hex()}".encode("utf-8")
        h = hashlib.sha1(raw).digest()
        n = int.from_bytes(h, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    # Validate
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(issue_id, str) or re.match(r"^ply_iss_[0-9A-Z]{10,}$", issue_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue_id is malformed")
    if not isinstance(body, dict):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object")

    required = ["message_direction", "sender_type", "body"]
    for k in required:
        if k not in body:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Missing required field: {k}")

    message_direction = body.get("message_direction")
    sender_type = body.get("sender_type")
    msg_body = body.get("body")
    sender_user_id = body.get("sender_user_id")
    sender_contact_id = body.get("sender_contact_id")

    if message_direction not in ["inbound", "outbound", "internal_note"]:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message_direction is invalid")
    if sender_type not in ["contact", "user", "system"]:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sender_type is invalid")
    if not isinstance(msg_body, str) or msg_body == "":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be a non-empty string")

    # sender fields consistency
    if sender_type == "user":
        if sender_user_id is None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_user_id is required when sender_type='user'")
        if not isinstance(sender_user_id, str) or re.match(r"^ply_usr_[0-9A-Z]{10,}$", sender_user_id) is None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_user_id is malformed")
        if sender_contact_id is not None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_contact_id must not be provided when sender_type='user'")
    elif sender_type == "contact":
        if sender_contact_id is None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_contact_id is required when sender_type='contact'")
        if not isinstance(sender_contact_id, str) or re.match(r"^ply_con_[0-9A-Z]{10,}$", sender_contact_id) is None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_contact_id is malformed")
        if sender_user_id is not None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_user_id must not be provided when sender_type='contact'")
    else:  # system
        if sender_user_id is not None or sender_contact_id is not None:
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sender_user_id/sender_contact_id must not be provided when sender_type='system'")

    # Business rule: internal_note => message_direction must be internal_note (already ensured by value; just keep)
    if message_direction == "internal_note" and message_direction != "internal_note":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "internal_note messages must have message_direction='internal_note'")

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # Workspace and issue existence
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    entities = _load("issues_messages_tags_forms.json")
    if not isinstance(entities, list):
        entities = []
    issue = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("id") == issue_id and e.get("entity_type") == "issue"), None)
    if not issue:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found")

    # Validate sender exists (if applicable)
    if sender_type == "user":
        users_teams = _load("users_teams.json")
        if not isinstance(users_teams, list):
            users_teams = []
        usr = next((u for u in users_teams if isinstance(u, dict) and u.get("workspace_id") == workspace_id and u.get("user_id") == sender_user_id), None)
        if not usr or usr.get("team_type") != "user":
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Sender user not found")
    if sender_type == "contact":
        customers = _load("customers.json")
        if not isinstance(customers, list):
            customers = []
        con = next((c for c in customers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("id") == sender_contact_id), None)
        if not con or con.get("entity_type") != "contact" or con.get("status") == "deleted":
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Sender contact not found")

    msg_row = {
        "id": _gen_ulid_like("ply_msg"),
        "workspace_id": workspace_id,
        "entity_type": "message",
        "status": "active",
        "issue_id": issue_id,
        "account_id": None,
        "contact_id": None,
        "title": None,
        "description": None,
        "priority": None,
        "assignee_user_id": None,
        "team_id": None,
        "ticket_form_id": None,
        "tag_ids": [],
        "snoozed_until": None,
        "message_direction": message_direction,
        "sender_type": sender_type,
        "sender_user_id": sender_user_id if sender_type == "user" else None,
        "sender_contact_id": sender_contact_id if sender_type == "contact" else None,
        "body": msg_body,
        "tag_name": None,
        "tag_color": None,
        "form_name": None,
        "form_schema": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    entities.append(msg_row)
    try:
        _save("issues_messages_tags_forms.json", entities)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist message")

    _append_log("success", None)
    return {"message": msg_row}

