        return resp

    if cursor is not None and not isinstance(cursor, str):
        status_code = "VALIDATION_ERROR"
        resp = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    # ---- workspace existence / scoping ----
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") in ("active", "suspended")), None)
    if not wsp:
        status_code = "NOT_FOUND"
        resp = _err("NOT_FOUND", "Workspace not found.")
        _log_request(None, status_code, int((time.time() - t0) * 1000))
        return resp

    entities = _load("issues_messages_tags_forms.json")
    tags = [
        r
        for r in entities
        if r.get("workspace_id") == workspace_id and r.get("entity_type") == "tag" and r.get("status") == status
    ]

    def _sort_key(r):
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt(r.get(sort))
            if dt is None:
                dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, str(r.get("id") or ""))
        # tag_name
        return (str(r.get("tag_name") or "").lower(), str(r.get("id") or ""))

    reverse = order == "desc"
    tags.sort(key=_sort_key, reverse=reverse)

    cur = _decode_cursor(cursor)
    start = 0
    if cur:
        if cur.get("workspace_id") != workspace_id or cur.get("sort") != sort or cur.get("order") != order or cur.get("status") != status:
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "cursor is invalid for this request.")
            _log_request(None, status_code, int((time.time() - t0) * 1000))
            return resp

        last = cur.get("last")
        last_id = cur.get("last_id")
        if not isinstance(last_id, str):
            status_code = "VALIDATION_ERROR"
            resp = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log_request(None, status_code, int((time.time() - t0) * 1000))
            return resp

        if sort in ("created_at", "updated_at"):
            last_dt = _parse_dt(last)
            if last_dt is None:
                status_code = "VALIDATION_ERROR"
                resp = _err("VALIDATION_ERROR", "cursor is invalid.")
                _log_request(None, status_code, int((time.time() - t0) * 1000))
                return resp

            def _after(r):
                rdt = _parse_dt(r.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                rid = str(r.get("id") or "")
                return (rdt, rid) > (last_dt, last_id) if not reverse else (rdt, rid) < (last_dt, last_id)

        else:
            if not isinstance(last, str):
                status_code = "VALIDATION_ERROR"
                resp = _err("VALIDATION_ERROR", "cursor is invalid.")
                _log_request(None, status_code, int((time.time() - t0) * 1000))
                return resp
            last_name = last.lower()

            def _after(r):
                rn = str(r.get("tag_name") or "").lower()
                rid = str(r.get("id") or "")
                return (rn, rid) > (last_name, last_id) if not reverse else (rn, rid) < (last_name, last_id)

        for i, r in enumerate(tags):
            if _after(r):
                start = i
                break
        else:
            start = len(tags)

    page = tags[start : start + limit]
    has_more = start + limit < len(tags)

    next_cursor = None
    if has_more and page:
        last_row = page[-1]
        if sort in ("created_at", "updated_at"):
            last_val_dt = _parse_dt(last_row.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            last_val = last_val_dt.isoformat()
        else:
            last_val = str(last_row.get("tag_name") or "")
        next_cursor = _encode_cursor(
            {
                "workspace_id": workspace_id,
                "status": status,
                "sort": sort,
                "order": order,
                "last": last_val,
                "last_id": str(last_row.get("id") or ""),
            }
        )

    resp = {
        "object": "list",
        "data": page,
        "total": len(tags),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    _log_request(None, status_code, int((time.time() - t0) * 1000))
    return resp

def pylon_get_ticket_forms(workspace_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_get_ticket_forms"
    status_code = "ok"

    # --- helpers ---
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, meta=None):
        nonlocal status_code
        status_code = status
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"ply_req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
                "status": status,
                "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
            }
            if isinstance(meta, dict):
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            # Must not raise; but don't mask programming errors elsewhere
            pass

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            d = json.loads(raw.decode("utf-8"))
            off = d.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # --- validation ---
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id) is None:
        e = _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
        _log("error", e["error"])
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, archived", field="status")
            _log("error", e["error"])
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        _log("error", e["error"])
        return e

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "form_name"):
        e = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, form_name", field="sort")
        _log("error", e["error"])
        return e

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")
        _log("error", e["error"])
        return e

    offset = _parse_cursor(cursor)
    if offset is None:
        e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        _log("error", e["error"])
        return e

    # --- workspace existence + visibility (ambient auth is assumed; enforce same-workspace scope only) ---
    workspaces = _load("workspaces.json")
    ws = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") != "deleted":
                ws = w
                break
    if ws is None:
        e = _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        _log("error", e["error"])
        return e

    # --- query ---
    rows = _load("issues_messages_tags_forms.json")
    if not isinstance(rows, list):
        rows = []

    forms = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("entity_type") != "ticket_form":
            continue
        # ticket_forms lifecycle uses active/archived; exclude deleted
        if r.get("status") not in ("active", "archived"):
            continue
        if status is not None and r.get("status") != status:
            continue
        forms.append(r)

    def _sort_key(x):
        v = x.get(sort)
        if v is None:
            return ""
        return v

    reverse = (order == "desc")
    try:
        forms.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # fallback deterministic sort
        forms.sort(key=lambda x: (str(_sort_key(x)), str(x.get("id", ""))), reverse=reverse)

    total = len(forms)
    page = forms[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    body = {
        "ticket_forms": page,
        "page": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    _log("ok", meta={"returned": len(page), "total": total})
    return body

