def pylon_create_webhook(workspace_id, webhook_url, webhook_secret=None, event_types=None, status=None, **_extra):
    import json, os, datetime, re, time, urllib.parse, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_create_webhook"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        raw = f"{ms}-{os.urandom(10).hex()}".encode("utf-8")
        h = hashlib.sha1(raw).digest()
        n = int.from_bytes(h, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    # Validate
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(webhook_url, str) or webhook_url.strip() == "":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_url is required")
    pr = urllib.parse.urlparse(webhook_url)
    if pr.scheme not in ("http", "https") or not pr.netloc:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_url must be a valid http(s) URL")
    if webhook_secret is not None and not isinstance(webhook_secret, str):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_secret must be a string")
    if event_types is None or not isinstance(event_types, list) or len(event_types) < 1 or any(not isinstance(x, str) or x.strip() == "" for x in event_types):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "event_types must be a non-empty array of strings")
    if status is not None and (not isinstance(status, str) or status not in ["enabled", "disabled"]):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid")
    if status is None:
        status = "enabled"

    allowed_events = set(["issue.created", "issue.updated", "issue.snoozed", "issue.resolved", "message.created", "contact.created", "article.created"])
    bad_events = [e for e in event_types if e not in allowed_events]
    if bad_events:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "event_types contains unsupported values", invalid_event_types=bad_events)

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # Workspace and plan limits
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    plan = ws.get("plan") or "free"
    limits = {"free": 1, "pro": 5, "business": 20, "enterprise": 100}
    limit = limits.get(plan, 1)

    kbwh = _load("knowledge_webhooks.json")
    if not isinstance(kbwh, list):
        kbwh = []

    existing = [r for r in kbwh if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("entity_type") == "webhook" and r.get("status") in ["enabled", "disabled"]]
    if len(existing) >= limit:
        _append_log("error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", f"Webhook limit reached for plan '{plan}'", limit=limit)

    # Conflict: same URL and overlapping event types among non-deleted
    for r in kbwh:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id or r.get("entity_type") != "webhook":
            continue
        if r.get("status") == "deleted":
            continue
        if r.get("webhook_url") == webhook_url:
            r_events = r.get("event_types") if isinstance(r.get("event_types"), list) else []
            if set(r_events) & set(event_types):
                _append_log("error", "CONFLICT")
                return _err("CONFLICT", "A webhook with the same URL and overlapping event_types already exists")

    # Store secret as non-plaintext (hash)
    stored_secret = None
    if webhook_secret is not None and webhook_secret != "":
        stored_secret = "sha256:" + hashlib.sha256(webhook_secret.encode("utf-8")).hexdigest()

    row = {
        "id": _gen_ulid_like("ply_whk"),
        "workspace_id": workspace_id,
        "entity_type": "webhook",
        "status": status,
        "knowledge_base_id": None,
        "kb_name": None,
        "kb_description": None,
        "article_title": None,
        "article_body": None,
        "article_slug": None,
        "published_at": None,
        "author_user_id": None,
        "webhook_url": webhook_url,
        "webhook_secret": stored_secret,
        "event_types": event_types,
        "last_delivery_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    kbwh.append(row)
    try:
        _save("knowledge_webhooks.json", kbwh)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist webhook")

    # Never return secret in plaintext
    resp = dict(row)
    resp["webhook_secret"] = None
    _append_log("success", None)
    return {"webhook": resp}

