    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_delete_webhook"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(webhook_id, str) or re.match(r"^ply_whk_[0-9A-HJKMNP-TV-Z]{10,}$", webhook_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_id is malformed")

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    kbwh = _load("knowledge_webhooks.json")
    if not isinstance(kbwh, list):
        kbwh = []

    idx = None
    row = None
    for i, r in enumerate(kbwh):
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("id") == webhook_id and r.get("entity_type") == "webhook":
            idx = i
            row = r
            break
    if row is None:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Webhook not found")

    # Soft-delete: disable then delete (retention policy => mark deleted)
    updated = dict(row)
    if updated.get("status") != "deleted":
        updated["status"] = "deleted"
        updated["updated_at"] = now_iso
        kbwh[idx] = updated

    try:
        _save("knowledge_webhooks.json", kbwh)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist webhook deletion")

    _append_log("success", None)
    return {"webhook": {"id": webhook_id, "deleted": True, "workspace_id": workspace_id}}

def pylon_get_identity(workspace_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _log(endpoint, workspace_id, credential_id, status, started_at, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        finished = time.time()
        row = {
            "id": f"rql_{int(finished*1000)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int(max(0, (finished - started_at) * 1000)),
            "ts": _now(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _usage_snapshot(credential_id):
        # Derive basic consumption from request_logs; if none exists, zeros.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("ts")
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                t = None
            if not t:
                continue
            if t >= window_start:
                per_min += 1
            if t >= day_start:
                per_day += 1
        # No declared hard limits in schema; expose observed counts.
        return {
            "requests_last_minute": per_min,
            "requests_today": per_day
        }

    started = time.time()
    endpoint = "pylon_get_identity"

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
            _log(endpoint, workspace_id if isinstance(workspace_id, str) else None, None, "error", started, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    workspaces = _load("workspaces.json")
    users_teams = _load("users_teams.json")

    # Ambient auth: choose any active user; if workspace_id specified, must be member of it.
    principal = None
    resolved_ws = None

    if workspace_id:
        resolved_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") in ["active", "suspended"]), None)
        if not resolved_ws:
            _log(endpoint, workspace_id, None, "error", started, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Workspace not found")
        principal = next(
            (
                u for u in users_teams
                if isinstance(u, dict)
                and u.get("team_type") == "user"
                and u.get("workspace_id") == workspace_id
                and u.get("user_status") in ["active", "invited"]
            ),
            None
        )
        if not principal:
            _log(endpoint, workspace_id, None, "error", started, {"code": "UNAUTHORIZED", "reason": "FORBIDDEN"})
            return _err("UNAUTHORIZED", "Forbidden: no access to workspace", reason="FORBIDDEN")
    else:
        # default workspace from credential context: pick any active workspace that has an active/invited user.
        for u in users_teams:
            if not isinstance(u, dict):
                continue
            if u.get("team_type") != "user" or u.get("user_status") not in ["active", "invited"]:
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == u.get("workspace_id") and w.get("status") in ["active", "suspended"]), None)
            if ws:
                principal = u
                resolved_ws = ws
                break
        if not principal or not resolved_ws:
            _log(endpoint, None, None, "error", started, {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No valid authentication context could be resolved")

    credential_id = principal.get("user_id")
    usage = _usage_snapshot(credential_id)

    entitlements = {
        "workspace": {
            "id": resolved_ws.get("id"),
            "slug": resolved_ws.get("slug"),
            "name": resolved_ws.get("name"),
            "status": resolved_ws.get("status"),
            "plan": resolved_ws.get("plan"),
            "default_timezone": resolved_ws.get("default_timezone"),
        },
        "principal": {
            "user_id": principal.get("user_id"),
            "email": principal.get("email"),
            "full_name": principal.get("full_name"),
            "user_role": principal.get("user_role"),
            "user_status": principal.get("user_status"),
        },
        "effective_scopes": ["read", "write"] if principal.get("user_role") in ["owner", "admin", "agent"] else ["read"],
        "usage": usage
    }

    _log(endpoint, resolved_ws.get("id"), credential_id, "ok", started)
    return entitlements

def pylon_get_contact(workspace_id, contact_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _log(endpoint, workspace_id, credential_id, status, started_at, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        finished = time.time()
        row = {
            "id": f"rql_{int(finished*1000)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int(max(0, (finished - started_at) * 1000)),
            "ts": _now(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_principal(ws_id):
        workspaces = _load("workspaces.json")
        users_teams = _load("users_teams.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id and w.get("status") in ["active", "suspended"]), None)
        if not ws:
            return None
        user = next(
            (
                u for u in users_teams
                if isinstance(u, dict)
                and u.get("team_type") == "user"
                and u.get("workspace_id") == ws_id
                and u.get("user_status") in ["active", "invited"]
            ),
            None
        )
        if not user:
            return None
        return {"workspace": ws, "principal": user, "credential_id": user.get("user_id")}

    started = time.time()
    endpoint = "pylon_get_contact"

    if not isinstance(workspace_id, str) or not re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log(endpoint, workspace_id if isinstance(workspace_id, str) else None, None, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
    if not isinstance(contact_id, str) or not re.match(r"^ply_con_[0-9A-Z]{10,}$", contact_id):
        _log(endpoint, workspace_id, None, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "contact_id is malformed", field="contact_id")

    ctx = _resolve_principal(workspace_id)
    if not ctx:
        _log(endpoint, workspace_id, None, "error", started, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authenticated or no access to workspace")

    customers = _load("customers.json")
    if not isinstance(customers, list):
        customers = []

    contact = next(
        (
            c for c in customers
            if isinstance(c, dict)
            and c.get("id") == contact_id
            and c.get("entity_type") == "contact"
        ),
        None
    )
    if not contact:
        _log(endpoint, workspace_id, ctx.get("credential_id"), "error", started, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Contact not found")

    if contact.get("workspace_id") != workspace_id:
        _log(endpoint, workspace_id, ctx.get("credential_id"), "error", started, {"code": "NOT_FOUND", "reason": "CROSS_WORKSPACE"})
        return _err("NOT_FOUND", "Contact not found")

    _log(endpoint, workspace_id, ctx.get("credential_id"), "ok", started)
    return {"contact": contact}

def pylon_update_contact(workspace_id, contact_id, contact_name=None, contact_email=None, contact_phone=None, account_id=None, subscription_level=None, billing_status=None, status=None, contact_history=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0172000" if __import__("os").path.isdir("./environment_mix/0172000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pylon_update_contact"
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_s, error_code=None, credential_id=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(ws_id):
        logs = _load_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < 120

    # Validate
    if not isinstance(workspace_id, str) or re.match(r"^ply_wsp_[0-9A-Z]{10,}$", workspace_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(contact_id, str) or re.match(r"^ply_con_[0-9A-Z]{10,}$", contact_id) is None:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_id is malformed")
    if contact_name is not None and (not isinstance(contact_name, str) or contact_name.strip() == ""):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_name must be a non-empty string")
    if contact_email is not None and (not isinstance(contact_email, str) or contact_email.strip() == ""):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_email must be a non-empty string")
    if contact_phone is not None and not isinstance(contact_phone, str):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_phone must be a string")
    if account_id is not None and (not isinstance(account_id, str) or re.match(r"^ply_acc_[0-9A-Z]{10,}$", account_id) is None):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed")
    if subscription_level is not None and subscription_level not in ["trial", "free", "starter", "pro", "enterprise"]:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subscription_level is invalid")
    if billing_status is not None and billing_status not in ["current", "past_due", "canceled"]:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "billing_status is invalid")
    if status is not None and status not in ["active", "archived", "deleted"]:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid")
    if contact_history is not None and not isinstance(contact_history, list):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_history must be an array")

    if not _rate_limit_ok(workspace_id):
        _append_log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # Workspace existence
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    customers = _load("customers.json")
    if not isinstance(customers, list):
        customers = []

    # Find contact in given workspace; do not claim UNAUTHORIZED for wrong workspace, just NOT_FOUND
    idx = None
    row = None
    for i, c in enumerate(customers):
        if isinstance(c, dict) and c.get("id") == contact_id:
            # if exists in different workspace, treat as not found to enforce scoping
            if c.get("workspace_id") != workspace_id:
                _append_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Contact not found")
            idx = i
            row = c
            break
    if row is None:
        _append_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found")
    if row.get("entity_type") != "contact":
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_id must reference a contact customer record")

    # Validate account linkage if provided
    if account_id is not None:
        acc = next((c for c in customers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("id") == account_id), None)
        if not acc or acc.get("entity_type") != "account" or acc.get("status") == "deleted":
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Account not found")

    # Enforce unique contact_email within workspace for non-deleted contacts
    if contact_email is not None:
        for c in customers:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            if c.get("entity_type") != "contact":
                continue
            if c.get("status") == "deleted":
                continue
            if c.get("id") != contact_id and c.get("contact_email") == contact_email:
                _append_log("error", "CONFLICT")
                return _err("CONFLICT", "contact_email must be unique within workspace for non-deleted contacts")

    # Status transitions for customers: active<->archived, active/archived->deleted, deleted terminal
    transitions = {
        "active": ["archived", "deleted"],
        "archived": ["active", "deleted"],
        "deleted": []
    }
    if status is not None:
        cur = row.get("status")
        if cur not in transitions:
            _append_log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current contact status is invalid")
        if status != cur and status not in transitions[cur]:
            _append_log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition contact from {cur} to {status}")

    updates = {}
    if contact_name is not None:
        updates["contact_name"] = contact_name
    if contact_email is not None:
        updates["contact_email"] = contact_email
    if contact_phone is not None:
        updates["contact_phone"] = contact_phone
    if account_id is not None:
        updates["account_id"] = account_id
    # These fields are not normally for contact per schema constraints; but tool allows them as metadata.
    if subscription_level is not None:
        updates["subscription_level"] = subscription_level
    if billing_status is not None:
        updates["billing_status"] = billing_status
    if status is not None:
        updates["status"] = status
    if contact_history is not None:
        updates["contact_history"] = contact_history

    if not updates:
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No fields to update")

    updated = dict(row)
    for k, v in updates.items():
        updated[k] = v
    updated["updated_at"] = now_iso
    customers[idx] = updated

    try:
        _save("customers.json", customers)
    except Exception:
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Failed to persist contact update")

    _append_log("success", None)
    return {"contact": updated}
